import{_ as e,c as i,o as r,a2 as l}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/privacy.md","filePath":"zh-CN/guide/privacy.md","lastUpdated":1793163976000}'),t={name:"zh-CN/guide/privacy.md"};function o(n,a,s,h,u,d){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>NueZip 被设计为完全离线优先的应用。你的隐私是我们的首要任务。</p><h2 id="仅本地设计" tabindex="-1">仅本地设计 <a class="header-anchor" href="#仅本地设计" aria-label="Permalink to &quot;仅本地设计&quot;">​</a></h2><ul><li>所有归档操作 — 压缩、解压、转换、加密 — 完全在你的 Mac 上运行。</li><li>NueZip 不会将你的文件或数据上传到任何外部服务器。</li><li>使用本应用无需账户或注册。</li><li>正常运行不需要互联网连接。</li></ul><h2 id="我们不收集的内容" tabindex="-1">我们不收集的内容 <a class="header-anchor" href="#我们不收集的内容" aria-label="Permalink to &quot;我们不收集的内容&quot;">​</a></h2><ul><li>我们不收集你的文件、文档或归档内容。</li><li>我们不追踪你的活动、浏览行为或使用模式。</li><li>我们不会向外部服务器发送任何文件元数据或个人信息。</li><li>我们不包含任何第三方分析、广告或追踪 SDK。</li><li>我们没有遥测系统。</li></ul><h2 id="本地存储的数据" tabindex="-1">本地存储的数据 <a class="header-anchor" href="#本地存储的数据" aria-label="Permalink to &quot;本地存储的数据&quot;">​</a></h2><p>以下数据仅存储在你的设备上：</p><ul><li><strong>应用设置</strong>：主题、语言偏好、压缩偏好</li><li><strong>许可证密钥</strong>：如已购买（安全存储在本地钥匙串中）</li><li><strong>最近文件列表</strong>：最近打开的归档，便于快速访问</li><li><strong>密码记录</strong>：如果你选择保存，则存储在本地钥匙串中</li><li><strong>日志</strong>：用于故障排除的调试日志（可随时删除）</li></ul><h2 id="应用使用的权限" tabindex="-1">应用使用的权限 <a class="header-anchor" href="#应用使用的权限" aria-label="Permalink to &quot;应用使用的权限&quot;">​</a></h2><ul><li><strong>文件与文件夹</strong>：读取归档文件和解压内容所需。</li><li><strong>Finder 扩展</strong>：可选，在 Finder 中添加右键上下文菜单项。</li><li><strong>通知</strong>：可选，用于长时间任务的完成提醒。</li></ul><p>你可以随时在 <strong>系统设置 → 隐私与安全性</strong> 中管理这些权限。</p><h2 id="应用内购买-许可证" tabindex="-1">应用内购买 / 许可证 <a class="header-anchor" href="#应用内购买-许可证" aria-label="Permalink to &quot;应用内购买 / 许可证&quot;">​</a></h2><p>许可证购买由 Apple 通过 Mac App Store 处理。NueZip 不会接收或存储你的支付信息。购买收据本地存储以验证所有权。</p><h2 id="第三方服务" tabindex="-1">第三方服务 <a class="header-anchor" href="#第三方服务" aria-label="Permalink to &quot;第三方服务&quot;">​</a></h2><p>NueZip 不包含任何第三方分析、广告或追踪服务。该应用完全自给自足。</p><h2 id="隐私请求" tabindex="-1">隐私请求 <a class="header-anchor" href="#隐私请求" aria-label="Permalink to &quot;隐私请求&quot;">​</a></h2><p>由于 NueZip 将所有数据本地存储在你设备上，我们在服务器上不持有任何个人数据。如果你对隐私有疑问，请联系我们。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>如有隐私相关问题，请在 <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 上提交 issue 或通过电子邮件联系我们。</p>',20)])])}const g=e(t,[["render",o]]);export{c as __pageData,g as default};
